#include <dlfcn.h>
#include <stdio.h>
int main() {
  void *handle;
  void (*foo)(int);
  handle = dlopen("./libfoo.so", RTLD_LAZY);
  if (!handle) {
    fprintf(stderr, "%s\n", dlerror());
    return 1;
  }
  foo = dlsym(handle, "foo");
  if (dlerror()) {
    fprintf(stderr, "%s\n", dlerror());
    dlclose(handle);
    return 1;
  }
  foo(10);
  dlclose(handle);
  return 0;
}
